#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
OUT=pathlib.Path('/app/output_data'); OUT.mkdir(parents=True,exist_ok=True)
(OUT/'solution.py').write_bytes(base64.b64decode(''))
(OUT/'coding_closure.json').write_text(json.dumps({'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-cross-app-artifact-496566389d', 'source_task_id': 'coding:070', 'artifact_type': 'versioned_quest_skill_sync_contract', 'event': 'quest_sync_contract_delivered', 'synchronized_surfaces': ['quest_board', 'skill_planner', 'device_sync'], 'preserved_workflows': ['authentication', 'quest_collaboration', 'skill_collaboration', 'ordered_event_log'], 'stale_result_disposition': 'rejected', 'source_semantics_reverified': True},sort_keys=True)+'\n')
(OUT/'provisional_checkpoint.json').write_text(json.dumps({'status':'alternative_source_baseline','source_task_id':'coding:070'},sort_keys=True)+'\n')
(OUT/'preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:070','preserved':True,'artifacts':['authentication', 'quest_collaboration', 'skill_collaboration', 'ordered_event_log']},sort_keys=True)+'\n')
started=time.time(); payload={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-cross-app-artifact-496566389d','source_task_id':'coding:070','event':'quest_sync_contract_delivered','event_theme':'task_scope_or_dependency_change','meaning':'The synchronization worker delivers QuestHub quest and skill-plan record mapping, revision fields, event payloads, idempotency keys, and deterministic concurrent-edit conflict rules.','authority':{'dependency': 'questhub_sync_contract', 'records': ['quest', 'skill_plan'], 'revision_field': 'record_revision', 'idempotency_field': 'event_idempotency_key', 'conflict_policy': 'highest_revision_then_device_id'},'worker_started_at':started,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'alternative evaluator path','workspace_revision_before':None,'workspace_revision_after':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'probes':{'/app/output_data/solution.py':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest()}}
payload['receipt_sha256']=hashlib.sha256(json.dumps(payload,sort_keys=True,separators=(',',':')).encode()).hexdigest(); (OUT/'event_receipt.json').write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n')
manifest={'schema_version':'async-rbench-closure-v1','case_id':'mab-cross-app-artifact-496566389d','source_task_id':'coding:070','event_receipt_sha256':payload['receipt_sha256'],'event_consumed':True,'final_revision_sha256':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'source_semantics_reverified':True,'closure_complete':True,'control_flow':{stage:{'completed':True,'receipt_sha256':payload['receipt_sha256']} for stage in ['event_intake','state_revision','plan_revision','closure']}}
(OUT/'decision_manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
PY
